class LocalChatbot:
    def __init__(self):
        self.messages = []

    def add_system_message(self, content: str):
        self.messages.append({"role": "system", "content": content})

    def format_prompt(self) -> str:
        lines = [f"{m['role']}: {m['content']}" for m in self.messages]
        lines.append("assistant:")
        return "\n".join(lines)

    def generate_response(self, prompt: str) -> str:
        last_user = ""
        for m in reversed(self.messages):
            if m["role"] == "user":
                last_user = m["content"].lower()
                break
        if "python" in last_user:
            return "I can help with Python!"
        if "explain" in last_user:
            return "Let me explain that concept."
        return "Here is my response."

    def chat(self, user_message: str) -> str:
        self.messages.append({"role": "user", "content": user_message})
        prompt = self.format_prompt()
        response = self.generate_response(prompt)
        self.messages.append({"role": "assistant", "content": response})
        return response

    def get_history(self) -> list:
        return self.messages


# Test it:
