print(resp2)
print(len(bot.get_history()))

class GenerationConfig:
    def __init__(self, temperature=0.7, top_p=0.9, top_k=50,
                 max_new_tokens=256, repetition_penalty=1.1):
        if isinstance(temperature, bool) or not isinstance(temperature, (int, float)) or not 0.0 <= temperature <= 2.0:
            raise ValueError(f"temperature must be between 0.0 and 2.0, got {temperature!r}")
        if isinstance(top_p, bool) or not isinstance(top_p, (int, float)) or not 0.0 <= top_p <= 1.0:
            raise ValueError(f"top_p must be between 0.0 and 1.0, got {top_p!r}")
        if isinstance(top_k, bool) or not isinstance(top_k, int) or not 1 <= top_k <= 100:
            raise ValueError(f"top_k must be an integer between 1 and 100, got {top_k!r}")
        if isinstance(max_new_tokens, bool) or not isinstance(max_new_tokens, int) or not 1 <= max_new_tokens <= 2048:
            raise ValueError(f"max_new_tokens must be an integer between 1 and 2048, got {max_new_tokens!r}")
        if isinstance(repetition_penalty, bool) or not isinstance(repetition_penalty, (int, float)) or not 1.0 <= repetition_penalty <= 2.0:
            raise ValueError(f"repetition_penalty must be between 1.0 and 2.0, got {repetition_penalty!r}")
        self.temperature = temperature
        self.top_p = top_p
        self.top_k = top_k
        self.max_new_tokens = max_new_tokens
        self.repetition_penalty = repetition_penalty

    def to_dict(self) -> dict:
        return {
            "temperature": self.temperature,
            "top_p": self.top_p,
            "top_k": self.top_k,
            "max_new_tokens": self.max_new_tokens,
            "repetition_penalty": self.repetition_penalty,
        }

    def describe(self) -> str:
        if self.temperature < 0.3:
            return "deterministic"
        if self.temperature <= 0.7:
            return "balanced"
        return "creative"


